from PIL import Image
import numpy as np
from collections import deque
a=np.array(Image.open('first_frame.png').convert('RGB'))
H,W=a.shape[:2]
# connected components for masks with 8-connectivity
def comps(mask, minsize=20):
    seen=np.zeros(mask.shape,bool); out=[]
    for y in range(H):
      for x in range(W):
       if mask[y,x] and not seen[y,x]:
        q=[(y,x)]; seen[y,x]=1; pts=[]
        for yy,xx in q:
         pts.append((xx,yy))
         for dy in (-1,0,1):
          for dx in (-1,0,1):
           if dy==0 and dx==0: continue
           nx,ny=xx+dx,yy+dy
           if 0<=nx<W and 0<=ny<H and mask[ny,nx] and not seen[ny,nx]:
            seen[ny,nx]=1;q.append((ny,nx))
        if len(pts)>=minsize:
         xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
         out.append((len(pts),(min(xs),min(ys),max(xs),max(ys))))
    return sorted(out,reverse=True)
rules={
'white': (a.min(2)>185),
'lightgray': ((a.min(2)>145)&(a.max(2)<230)),
'dark': (a.max(2)<55),
'red': ((a[:,:,0]>100)&(a[:,:,0]>a[:,:,1]+35)&(a[:,:,0]>a[:,:,2]+25)),
'brown': ((a[:,:,0]>100)&(a[:,:,0]>a[:,:,2]+25)&(a[:,:,1]>55)&(a[:,:,1]>a[:,:,2]+5)&(a[:,:,0]<210)),
'orange_yellow': ((a[:,:,0]>170)&(a[:,:,1]>110)&(a[:,:,2]<100)),
'blue': ((a[:,:,2]>a[:,:,0]+25)&(a[:,:,2]>80)),
}
for name,m in rules.items():
 print('\\n',name,m.sum())
 for c in comps(m,30)[:20]: print(c)
# print a color key at selected positions and region means
print('\\nregion means')
regions=[('topL',0,0,80,50),('leftdark',0,40,120,120),('center',70,70,160,130),('toaster?',170,75,250,135),('robot?',40,100,150,170),('tablefront',0,130,256,192),('right',150,50,256,160)]
for n,x0,y0,x1,y1 in regions:
 p=a[y0:y1,x0:x1].reshape(-1,3)
 print(n,p.mean(0).round(1),np.median(p,0),p.min(0),p.max(0))
